import React, { useState } from 'react';
import { searchTracks, getAudioAnalysis } from '../services/api';

const TrackSearch = ({ onTrackSelected }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [selectedTrack, setSelectedTrack] = useState(null);

  const handleSearch = async () => {
    console.log('Search button clicked!');
    console.log('Search term:', searchTerm);
    try {
      const results = await searchTracks(searchTerm);
      console.log('Search results:', results);
      setFilteredTracks(results);
    } catch (error) {
      console.error('Error during search:', error);
    }
  };

  const selectTrackForAnalysis = (track) => {
    console.log('Selected track for analysis:', track);
    setSelectedTrack(track);
    // You can trigger the analysis function here or in another component
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search for a track..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      <div>
        {filteredTracks.length > 0 ? (
          <table>
            <thead>
              <tr>
                <th>Track Name</th>
                <th>Album</th>
                <th>Artist</th>
                <th>Year</th>
                <th>Select</th>
              </tr>
            </thead>
            <tbody>
              {filteredTracks.map((track) => (
                <tr key={track.id}>
                  <td>{track.name || 'Unknown Track'}</td>
                  <td>{track.album?.name || 'Unknown Album'}</td>
                  <td>{track.artists?.[0]?.name || 'Unknown Artist'}</td>
                  <td>{track.album?.release_date?.split('-')[0] || 'Unknown Year'}</td>
                  <td>
                    <button onClick={() => selectTrackForAnalysis(track)}>Select</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No results found</p>
        )}
      </div>
      {selectedTrack && (
        <div>
          <h3>Selected Track for Analysis:</h3>
          <p>{selectedTrack.name} by {selectedTrack.artists?.[0]?.name}</p>
        </div>
      )}
    </div>
  );
};

export default TrackSearch;
